PlanRecord ProjectStateDocument::plan() const
{
    const json& stored = m_doc["plan"];
    PlanRecord  record;
    record.seq        = stored.value("seq", std::uint64_t(0));
    record.updated_at = stored.value("updatedAt", "");
    record.headline   = stored.value("headline", "");
    record.validity = stored.value("validity", "current");
    record.invalidated_by = stored.value("invalidatedBy", "");
    if (stored.contains("decisions") && stored["decisions"].is_array())
        for (const json& entry : stored["decisions"])
            record.decisions.push_back({entry.value("topic", ""), entry.value("statement", ""),
                                        entry.value("confidence", ""), entry.value("alternative", "")});
    const auto read_lines = [&stored](const char* key, std::vector<std::string>& into) {
        if (!stored.contains(key) || !stored[key].is_array())
            return;
        for (const json& entry : stored[key])
            if (entry.is_string())
                into.push_back(entry.get<std::string>());
    };
    read_lines("assumptions", record.assumptions);
    read_lines("risks", record.risks);
    return record;
}

PlanRecord ProjectStateDocument::set_plan(PlanRecord record, const std::string& timestamp)
{
    record.seq        = next_seq();
    record.updated_at = timestamp;
    json& stored      = m_doc["plan"];
    if (!stored.is_object())
        stored = json::object();
    stored["seq"]         = record.seq;
    stored["updatedAt"]   = record.updated_at;
    stored["headline"]    = record.headline;
    stored["validity"]    = "current";
    stored["invalidatedBy"] = "";
    stored["decisions"]   = json::array();
    for (const PlanDecision& decision : record.decisions)
        stored["decisions"].push_back({{"topic", decision.topic},
                                       {"statement", decision.statement},
                                       {"confidence", decision.confidence},
                                       {"alternative", decision.alternative}});
    stored["assumptions"] = record.assumptions;
    stored["risks"]       = record.risks;
    touch();
    return record;
}

bool ProjectStateDocument::mark_plan_needs_reassessment(const std::string& reason)
{
    json& stored = m_doc["plan"];
    if (!stored.is_object() || (stored.value("headline", "").empty() &&
                                (!stored.contains("decisions") || stored["decisions"].empty())))
        return false;
    if (stored.value("validity", "current") == "needs_reassessment" &&
        stored.value("invalidatedBy", "") == reason)
        return false;
    stored["validity"] = "needs_reassessment";
    stored["invalidatedBy"] = reason;
    touch();

    if (m_config.in_memory) {
        // No project to follow and nowhere to mirror to: this session is its
        // own boundary, and it needs an identity now because ids are minted
        // from it.
        m_config.recovery_root.clear();
        m_document.initialize_identity("p-" + m_config.uuid(), "l-" + m_config.uuid(), m_config.clock());
        return;
    }
    m_subscription = m_workspace.subscribe([this](const Workspace::WorkspaceChanged& change) {
        on_workspace_changed(change);
    });
    m_edit_subscription = m_workspace.subscribe_edits([this](const Workspace::WorkspaceEdit& edit) { on_edit(edit); });
}

void ProjectPersistence::on_edit(const Workspace::WorkspaceEdit& edit)
{
    // The edit belongs to whatever project is really open now.
    resolve_pending_boundary();
    ChangeEntry entry;
    entry.kind   = edit_kind_name(edit.kind);
    entry.actor    = edit.actor == Workspace::EditActor::Person ? "person" : "agent";
    entry.external = edit.actor == Workspace::EditActor::ExternalTool;
    entry.label  = edit.label;
    entry.from   = edit.before;
    entry.to     = edit.after;
    entry.preset = edit.preset;
    entry.key    = edit.key;
    const ChangeEntry stored = m_document.add_change(std::move(entry), m_config.clock());
    m_document.mark_plan_needs_reassessment(stored.label.empty() ? "The project changed" : stored.label);
    // A paint session is a burst of edits; the owner's pacing timer writes them.
    commit();
    if (m_change_added)
        m_change_added(stored);
}

